<?php
require_once __DIR__ . '/../includes/layout.php';

// Limit report rows to the signed-in role.
$me=require_login();$pdo=db();$params=[];$where=''; if($me['role']==='teacher'){$where=' WHERE c.teacher_id=?';$params[]=$me['id'];}elseif($me['role']==='student'){$where=' WHERE u.id=?';$params[]=$me['id'];}$sql="SELECT u.full_name,c.class_code,COUNT(a.id) sessions,SUM(a.status IN ('present','late')) attended,ROUND(100*SUM(a.status IN ('present','late'))/NULLIF(COUNT(a.id),0),1) rate FROM attendance a JOIN users u ON u.id=a.student_id JOIN classes c ON c.id=a.class_id $where GROUP BY u.id,c.id ORDER BY u.full_name,c.class_code";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();page_start('Attendance Reports',$me);?><section class="panel"><div class="panel-heading"><div><h2>Attendance summary</h2><p>Present and late statuses count as attended sessions.</p></div></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>Sessions</th><th>Attended</th><th>Rate</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['class_code'])?></td><td><?=$r['sessions']?></td><td><?=$r['attended']?></td><td><?=e((string)$r['rate'])?>%</td></tr><?php endforeach;?></tbody></table></div></section><?php page_end(); ?>
